import express from 'express';

import { SERVER_PORT, DIST_DIR } from './config';
import { projectsRouter } from './routes/projects';
import { conversationsRouter } from './routes/conversations';
import { eventsRouter } from './routes/events';
import { startWatching } from './services/watcher';

const app = express();

app.use(express.json({ limit: '5mb' }));

/* -------------------------------------------------------------------------- */
/*  API routes                                                                */
/* -------------------------------------------------------------------------- */

app.use('/api/projects', projectsRouter);
app.use('/api/conversations', conversationsRouter);
app.use('/api/events', eventsRouter);

app.get('/api/health', (_req, res) => {
  res.json({ ok: true });
});

/* -------------------------------------------------------------------------- */
/*  Production: serve the built front-end                                     */
/* -------------------------------------------------------------------------- */

if (process.env.NODE_ENV === 'production') {
  app.use(express.static(DIST_DIR));

  // SPA fallback: any non-/api GET returns index.html.
  app.get(/^\/(?!api\/).*/, (_req, res) => {
    res.sendFile(path.join(DIST_DIR, 'index.html'));
  });
}

/* -------------------------------------------------------------------------- */
/*  Listen                                                                    */
/* -------------------------------------------------------------------------- */

app.listen(SERVER_PORT, () => {
  // eslint-disable-next-line no-console
  console.log(`[workstation] server listening on http://localhost:${SERVER_PORT}`);
});

// Start watching the conversations data dir for live updates (SSE via
// /api/events). Failures are handled inside startWatching (graceful degrade).
void startWatching();

