import { useEffect, useRef, useState } from 'react';

/** Mirror of the server's WorkstationEvent (server/services/eventBus.ts). */
export interface ServerEvent {
  type: 'conversations-changed' | 'projects-changed';
  slug?: string;
  id?: string;
}

/**
 * Subscribe to the server's Server-Sent-Events stream (/api/events) and invoke
 * `onEvent` for each event. EventSource reconnects automatically on drop.
 * Returns the live connection state for an optional "live" indicator.
 */
export function useServerEvents(onEvent: (event: ServerEvent) => void): boolean {
  const handler = useRef(onEvent);
  handler.current = onEvent;
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const source = new EventSource('/api/events');

    source.onopen = () => setConnected(true);
    source.onerror = () => setConnected(false);
    source.onmessage = (message) => {
      try {
        handler.current(JSON.parse(message.data) as ServerEvent);
      } catch {
        /* ignore malformed frames */
      }
    };

    return () => source.close();
  }, []);

  return connected;
}

