import type {
  Conversation,
  ConversationMeta,
  ProjectSummary,
} from '../types/conversation';

/**
 * Typed fetch wrapper over the Express API mounted at /api.
 * Every helper throws an `ApiError` on a non-2xx response so callers can
 * surface a friendly message.
 */

export class ApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      headers: { Accept: 'application/json', ...(init?.headers ?? {}) },
      ...init,
    });
  } catch (cause) {
    throw new ApiError(
      'Impossible de joindre le serveur. Vérifiez qu’il est démarré.',
      0,
    );
  }

  if (!res.ok) {
    let detail = '';
    try {
      const body = (await res.json()) as { error?: string; message?: string };
      detail = body.error ?? body.message ?? '';
    } catch {
      detail = res.statusText;
    }
    throw new ApiError(
      detail || `La requête a échoué (HTTP ${res.status}).`,
      res.status,
    );
  }

  return (await res.json()) as T;
}

/* -------------------------------------------------------------------------- */
/*  Projects                                                                  */
/* -------------------------------------------------------------------------- */

export async function listProjects(
  options?: { refresh?: boolean },
): Promise<ProjectSummary[]> {
  const query = options?.refresh ? '?refresh=1' : '';
  const data = await request<{ projects: ProjectSummary[] }>(
    `/api/projects${query}`,
  );
  return data.projects;
}

/* -------------------------------------------------------------------------- */
/*  Conversations                                                             */
/* -------------------------------------------------------------------------- */

export async function getConversations(
  options?: { project?: string },
): Promise<ConversationMeta[]> {
  const query = options?.project
    ? `?project=${encodeURIComponent(options.project)}`
    : '';
  const data = await request<{ conversations: ConversationMeta[] }>(
    `/api/conversations${query}`,
  );
  return data.conversations;
}

export async function getConversation(
  slug: string,
  id: string,
): Promise<Conversation> {
  return request<Conversation>(
    `/api/conversations/${encodeURIComponent(slug)}/${encodeURIComponent(id)}`,
  );
}

export async function saveConversation(
  conversation: Conversation,
): Promise<Conversation> {
  const { project, id } = conversation;
  return request<Conversation>(
    `/api/conversations/${encodeURIComponent(project.slug)}/${encodeURIComponent(id)}`,
    {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(conversation),
    },
  );
}

