import { Router } from 'express';

import { subscribe } from '../services/eventBus';

/** Heartbeat interval. Keeps proxies/browsers from idling the stream out. */
const HEARTBEAT_MS = 25_000;

export const eventsRouter = Router();

/**
 * GET /api/events — Server-Sent Events stream.
 *
 * Emits every event published on the in-process event bus as a `data:` line so
 * the dashboard and any open conversation can refresh when files change.
 *
 * Each message is flushed immediately (no buffering): we set the SSE headers,
 * disable proxy buffering via X-Accel-Buffering, and flushHeaders() before
 * writing. A `: ping` comment every 25s keeps the connection alive. On client
 * disconnect ('close') we unsubscribe and clear the heartbeat so nothing leaks.
 */
eventsRouter.get('/', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');
  res.flushHeaders?.();

  // Initial comment so the client sees bytes immediately and the stream opens.
  res.write(': connected\n\n');

  const unsubscribe = subscribe((event) => {
    res.write(`data: ${JSON.stringify(event)}\n\n`);
  });

  const heartbeat = setInterval(() => {
    res.write(': ping\n\n');
  }, HEARTBEAT_MS);

  req.on('close', () => {
    clearInterval(heartbeat);
    unsubscribe();
  });
});

