import { useCallback, useEffect, useState } from 'react';
import type { Conversation, Item } from '../types/conversation';
import { ApiError, getConversation, saveConversation } from '../lib/api';

type LoadState = 'idle' | 'loading' | 'ready' | 'error';
type SaveState = 'idle' | 'saving' | 'saved' | 'error';

export interface UseConversation {
  /** Local, editable copy of the conversation. */
  conversation: Conversation | null;
  loadState: LoadState;
  loadError: string | null;
  saveState: SaveState;
  saveError: string | null;
  /** True when the last save failed because the file changed on disk (409). */
  conflict: boolean;
  /** True when the local copy differs from the last persisted copy. */
  dirty: boolean;
  /** Patch a single item in the local copy (by id). */
  updateItem: (id: string, patch: Partial<Item>) => void;
  /** Persist the local copy; returns the re-read server copy on success. */
  save: () => Promise<void>;
  reload: () => void;
}

function applyPatch(item: Item, patch: Partial<Item>): Item {
  // The discriminated union forbids changing `kind`, so we keep it intact and
  // merge the rest. Callers only ever patch fields valid for the item's kind.
  return { ...item, ...patch, kind: item.kind } as Item;
}

export function useConversation(slug: string, id: string): UseConversation {
  const [conversation, setConversation] = useState<Conversation | null>(null);
  const [serverSnapshot, setServerSnapshot] = useState<string>('');
  const [loadState, setLoadState] = useState<LoadState>('idle');
  const [loadError, setLoadError] = useState<string | null>(null);
  const [saveState, setSaveState] = useState<SaveState>('idle');
  const [saveError, setSaveError] = useState<string | null>(null);
  const [conflict, setConflict] = useState<boolean>(false);

  const load = useCallback(() => {
    let cancelled = false;
    setLoadState('loading');
    setLoadError(null);

    getConversation(slug, id)
      .then((data) => {
        if (cancelled) return;
        setConversation(data);
        setServerSnapshot(JSON.stringify(data));
        setLoadState('ready');
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        const message =
          err instanceof ApiError
            ? err.message
            : 'Erreur inattendue lors du chargement.';
        setLoadError(message);
        setLoadState('error');
      });

    return () => {
      cancelled = true;
    };
  }, [slug, id]);

  useEffect(() => load(), [load]);

  const updateItem = useCallback((itemId: string, patch: Partial<Item>) => {
    setSaveState('idle');
    setConversation((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        items: prev.items.map((item) =>
          item.id === itemId ? applyPatch(item, patch) : item,
        ),
      };
    });
  }, []);

  const save = useCallback(async () => {
    if (!conversation) return;
    setSaveState('saving');
    setSaveError(null);
    setConflict(false);
    try {
      const persisted = await saveConversation(conversation);
      setConversation(persisted);
      setServerSnapshot(JSON.stringify(persisted));
      setSaveState('saved');
    } catch (err: unknown) {
      const message =
        err instanceof ApiError
          ? err.message
          : 'Erreur inattendue lors de l’enregistrement.';
      // 409 = the file changed on disk since it was loaded (stale tab). We did
      // NOT overwrite it; prompt the user to reload the latest version.
      if (err instanceof ApiError && err.status === 409) {
        setConflict(true);
      }
      setSaveError(message);
      setSaveState('error');
    }
  }, [conversation]);

  const dirty =
    conversation !== null && JSON.stringify(conversation) !== serverSnapshot;

  return {
    conversation,
    loadState,
    loadError,
    saveState,
    saveError,
    conflict,
    dirty,
    updateItem,
    save,
    reload: load,
  };
}

