export function ConversationPage() {
  const { slug = '', id = '' } = useParams();
  const {
    conversation,
    loadState,
    loadError,
    saveState,
    saveError,
    conflict,
    dirty,
    updateItem,
    save,
    reload,
  } = useConversation(slug, id);

  const [tocOpen, setTocOpen] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const [externalChange, setExternalChange] = useState(false);

  const items = conversation?.items ?? [];
  const anchors = items.map((i) => itemAnchor(i.id));
  const activeAnchor = useScrollSpy(anchors);

  // Live updates: if Claude (or another tab) rewrites this file, refresh when
  // we have no unsaved edits; otherwise surface a non-destructive banner.
  useServerEvents(
    useCallback(
      (event) => {
        if (event.type !== 'conversations-changed') return;
        if (event.slug && event.slug !== slug) return;
        if (event.id && event.id !== id) return;
        if (dirty) {
          setExternalChange(true);
        } else {
          reload();
          setToast('Conversation mise à jour');
        }
      },
      [slug, id, dirty, reload],
    ),
  );

  useEffect(() => {
    if (saveState === 'saved') {
      setToast('Réponses enregistrées · Claude pourra les relire');
    }
  }, [saveState]);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    if (!tocOpen) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setTocOpen(false);
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [tocOpen]);

