          <div className="h-48 animate-pulse rounded-lg bg-paper-card" />
        </div>
      </Wrap>
    );
  }

  if (loadState === 'error' || !conversation) {
    return (
      <Wrap>
        <div className="my-16 rounded-lg border border-line bg-paper-card p-10 text-center">
