  --shadow-warm-sm: 0 1px 2px rgba(33, 29, 23, 0.06);
  --shadow-lift: 0 2px 4px rgba(33, 29, 23, 0.05), 0 18px 40px -20px rgba(33, 29, 23, 0.3);
}

/* ------------------------------------------------------------------------- */
/*  Base                                                                     */
/* ------------------------------------------------------------------------- */
@layer base {
  html {
    scroll-behavior: smooth;
    scroll-padding-top: 6rem; /* keep anchored items clear of the sticky bar */
  }

  body {
    background-color: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
