import { useCallback, useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import type { Item } from '../types/conversation';
import { itemCountsTowardCompletion } from '../types/conversation';
import { useConversation } from '../hooks/useConversation';
import { useScrollSpy } from '../hooks/useScrollSpy';
import { useServerEvents } from '../hooks/useServerEvents';
import { itemAnchor } from '../lib/conversation';
import { formatRelative } from '../lib/format';
import { TocList } from '../components/conversation/Toc';
import { DecisionItem } from '../components/items/DecisionItem';
import { QuestionItem } from '../components/items/QuestionItem';
import { ApprovalItem } from '../components/items/ApprovalItem';
import { ChecklistItem } from '../components/items/ChecklistItem';
import { ProposalItem } from '../components/items/ProposalItem';
import { NoteItem } from '../components/items/NoteItem';
import { RatingItem } from '../components/items/RatingItem';
import { Button } from '../components/ui/Button';
import { StatusPill } from '../components/ui/StatusPill';

export function ConversationPage() {
  const { slug = '', id = '' } = useParams();
  const {
    conversation,
    loadState,
    loadError,
    saveState,
    saveError,
    conflict,
    dirty,
    updateItem,
    save,
    reload,
  } = useConversation(slug, id);

  const [tocOpen, setTocOpen] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const [externalChange, setExternalChange] = useState(false);

  const items = conversation?.items ?? [];
  const anchors = items.map((i) => itemAnchor(i.id));
  const activeAnchor = useScrollSpy(anchors);

  // Live updates: if Claude (or another tab) rewrites this file, refresh when
  // we have no unsaved edits; otherwise surface a non-destructive banner.
  useServerEvents(
    useCallback(
      (event) => {
        if (event.type !== 'conversations-changed') return;
        if (event.slug && event.slug !== slug) return;
        if (event.id && event.id !== id) return;
        if (dirty) {
          setExternalChange(true);
        } else {
          reload();
          setToast('Conversation mise à jour');
        }
      },
      [slug, id, dirty, reload],
    ),
  );

  useEffect(() => {
    if (saveState === 'saved') {
      setToast('Réponses enregistrées · Claude pourra les relire');
    }
  }, [saveState]);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    if (!tocOpen) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setTocOpen(false);
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [tocOpen]);

  if (loadState === 'loading' || loadState === 'idle') {
    return (
      <Wrap>
        <div className="space-y-5 py-12">
          <div className="h-10 w-2/3 animate-pulse rounded bg-paper-deep" />
          <div className="h-48 animate-pulse rounded-lg bg-paper-card" />
          <div className="h-48 animate-pulse rounded-lg bg-paper-card" />
        </div>
      </Wrap>
    );
  }

  if (loadState === 'error' || !conversation) {
    return (
      <Wrap>
        <div className="my-16 rounded-lg border border-line bg-paper-card p-10 text-center">
          <p className="numeral text-5xl text-copper/25">404</p>
          <p className="mt-3 font-display text-2xl text-ink">Conversation introuvable</p>
          <p className="mt-2 text-sm text-ink-soft">
            {loadError ?? 'Cette conversation n’existe pas ou a été déplacée.'}
          </p>
          <Link to="/conversations" className="mt-5 inline-block text-sm font-medium text-copper hover:underline">
            ← Toutes les conversations
          </Link>
        </div>
      </Wrap>
    );
  }

  const counting = items.filter(itemCountsTowardCompletion);
  const answered = counting.filter((i) => i.status === 'answered').length;
  const total = counting.length;
  const pct = total > 0 ? Math.round((answered / total) * 100) : 0;

  return (
    <Wrap>
      {/* Mobile sticky TOC trigger */}
      <div className="sticky top-14 z-30 -mx-5 border-b border-line bg-paper/90 px-5 py-2.5 backdrop-blur sm:-mx-8 sm:px-8 xl:hidden">
        <button
          onClick={() => setTocOpen(true)}
          className="flex w-full items-center gap-3 text-left"
          aria-haspopup="dialog"
