          <span className="font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">Sommaire</span>
          <span className="h-1 flex-1 overflow-hidden rounded-full bg-paper-deep">
            <span className="block h-full rounded-full bg-copper/70 transition-all" style={{ width: `${pct}%` }} />
          </span>
          <span className="font-mono text-xs text-ink-soft">{answered}/{total}</span>
          <span aria-hidden className="text-ink-faint">☰</span>
        </button>
      </div>

      <div className="py-8 sm:py-10 xl:grid xl:grid-cols-[minmax(0,1fr)_13.5rem] xl:gap-10 xl:py-12">
        {/* Main reading column */}
        <div className="min-w-0 max-w-2xl">
          <header>
            <nav className="flex items-center gap-2 font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
              <Link to="/" className="hover:text-copper">Projets</Link>
              <span aria-hidden>/</span>
              <Link to={`/conversations?project=${conversation.project.slug}`} className="hover:text-copper">
                {conversation.project.name}
              </Link>
            </nav>

            <div className="mt-3 flex items-start justify-between gap-4">
              <h1 className="font-display text-4xl leading-[1.1] text-ink">{conversation.title}</h1>
              <StatusPill status={conversation.status} className="mt-1.5 shrink-0" />
            </div>

            {conversation.summary && (
              <p className="mt-4 max-w-prose text-base leading-relaxed text-ink-soft">{conversation.summary}</p>
            )}

            <div className="mt-5 flex flex-wrap items-center gap-3">
              <span className="h-1.5 w-32 overflow-hidden rounded-full bg-paper-deep">
                <span className="block h-full rounded-full bg-copper transition-all" style={{ width: `${pct}%` }} />
              </span>
              <span className="font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
                {answered}/{total} traités · maj {formatRelative(conversation.updatedAt)}
              </span>
            </div>
          </header>

          {externalChange && (
            <div className="mt-6 flex items-center gap-3 rounded-lg border border-status-progress/40 bg-status-progress-bg/60 px-4 py-3 text-sm text-status-progress">
              <span className="flex-1">Ce fichier a changé sur le disque (Claude l’a peut-être réécrit).</span>
              <button
                onClick={() => { setExternalChange(false); reload(); }}
                className="font-medium underline underline-offset-2"
              >
                Recharger
              </button>
            </div>
          )}

          <hr className="rule my-8" />

          <div className="space-y-12">
            {items.map((item, index) => (
              <ItemRenderer key={item.id} item={item} index={index} onChange={(patch) => updateItem(item.id, patch)} />
