          </div>

          {/* Sticky action bar */}
          <div className="sticky bottom-0 z-20 mt-10 -mx-5 border-t border-line bg-paper/92 px-5 py-3.5 backdrop-blur sm:-mx-8 sm:px-8">
            <div className="flex items-center gap-3">
              <span className="text-sm text-ink-soft">
                {dirty ? 'Modifications non enregistrées' : 'Tout est à jour'}
              </span>
              {saveState === 'error' && saveError && (
                <span className="hidden text-sm text-copper-deep sm:inline">{saveError}</span>
              )}
              {conflict ? (
                <Button variant="copper" className="ml-auto" onClick={() => reload()}>
                  Recharger la dernière version
                </Button>
              ) : (
                <Button
                  variant="copper"
                  className="ml-auto"
                  onClick={() => void save()}
                  loading={saveState === 'saving'}
                  disabled={!dirty && saveState !== 'error'}
                >
                  Enregistrer les réponses
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Desktop TOC rail */}
        <aside className="hidden xl:block">
          <div className="sticky top-20">
            <p className="eyebrow mb-3 text-ink-faint">Sommaire</p>
            <TocList items={items} activeId={activeAnchor} />
          </div>
        </aside>
      </div>

      {/* Mobile TOC drawer */}
      {tocOpen && (
        <div className="fixed inset-0 z-50 xl:hidden" role="dialog" aria-modal="true" aria-label="Sommaire">
          <div className="absolute inset-0 bg-ink/30 backdrop-blur-sm" onClick={() => setTocOpen(false)} />
