import { CommentField, ItemShell, stampAnsweredAt } from '../conversation/ItemShell';

interface Props {
  item: ChecklistItemType;
  index: number;
  onChange: (patch: Partial<Item>) => void;
}

export function ChecklistItem({ item, index, onChange }: Props) {
  const checked = item.response?.checkedIds ?? [];
  const requireAll = item.requireAll ?? false;

  function commit(next: string[]) {
    const hasAnswer = requireAll ? next.length === item.options.length : next.length > 0;
    onChange({
      response: next.length > 0 ? { checkedIds: next } : undefined,
      status: hasAnswer ? 'answered' : next.length > 0 ? 'pending' : 'pending',
      answeredAt: stampAnsweredAt(item.answeredAt, hasAnswer),
    });
  }

  function toggle(id: string) {
    commit(checked.includes(id) ? checked.filter((c) => c !== id) : [...checked, id]);
  }

  return (
    <ItemShell
      item={item}
      index={index}
      comment={<CommentField value={item.comment ?? ''} onChange={(v) => onChange({ comment: v || undefined })} />}
    >
      {requireAll && (
        <p className="mb-2 font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
          Tout cocher pour valider · {checked.length}/{item.options.length}
        </p>
      )}
      <ul className="space-y-1.5">
        {item.options.map((option) => {
          const isChecked = checked.includes(option.id);
          return (
            <li key={option.id}>
              <button
                type="button"
                role="checkbox"
                aria-checked={isChecked}
                onClick={() => toggle(option.id)}
                className={`flex w-full items-start gap-3 rounded-lg border p-3 text-left transition-colors ${
                  isChecked ? 'border-status-done/50 bg-status-done-bg/50' : 'border-line bg-paper-raised hover:border-copper/40'
                }`}
              >
                <span
                  aria-hidden
                  className={`mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-[6px] border transition-colors ${
                    isChecked ? 'border-status-done bg-status-done text-paper-raised' : 'border-line bg-paper'
                  }`}
                >
                  {isChecked && <span className="text-xs font-bold leading-none">✓</span>}
                </span>
                <span className="flex-1">
                  <span className={`font-medium ${isChecked ? 'text-ink' : 'text-ink'}`}>{option.label}</span>
                  {option.description && (
                    <span className="mt-0.5 block text-sm leading-relaxed text-ink-soft">{option.description}</span>
                  )}
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </ItemShell>
  );
}
import type { Item, RatingItem as RatingItemType } from '../../types/conversation';
import { CommentField, ItemShell } from '../conversation/ItemShell';

interface Props {
  item: RatingItemType;
  index: number;
  onChange: (patch: Partial<Item>) => void;
}

export function RatingItem({ item, index, onChange }: Props) {
  const value = item.response?.value;
  const style = item.style ?? 'dots';
  const values = Array.from({ length: item.max }, (_, i) => i + 1);

  function commit(next: number) {
    const cleared = value === next; // click the active value again to clear
    onChange({
      response: cleared ? undefined : { value: next },
      status: cleared ? 'pending' : 'answered',
      answeredAt: cleared ? undefined : item.answeredAt ?? new Date().toISOString(),
    });
  }

  return (
    <ItemShell
      item={item}
      index={index}
      comment={<CommentField value={item.comment ?? ''} onChange={(v) => onChange({ comment: v || undefined })} />}
    >
      {style === 'labels' ? (
        <div className="flex flex-wrap gap-2">
          {values.map((v) => {
            const active = value === v;
            return (
              <button
                key={v}
                type="button"
                aria-pressed={active}
                onClick={() => commit(v)}
                className={`rounded-lg border px-3.5 py-2 text-sm font-medium transition-colors ${
                  active ? 'border-copper bg-copper-tint/60 text-copper-deep' : 'border-line bg-paper-raised text-ink hover:border-copper/45'
                }`}
              >
                <span className="numeral mr-1.5 text-copper">{v}</span>
                {item.labels?.[v - 1] ?? ''}
              </button>
            );
          })}
        </div>
      ) : (
        <div className="flex items-center gap-2">
          {values.map((v) => {
            const active = value !== undefined && v <= value;
            const isStars = style === 'stars';
            return (
              <button
                key={v}
                type="button"
                aria-label={`${v} sur ${item.max}`}
                aria-pressed={value === v}
                onClick={() => commit(v)}
                className={`grid place-items-center transition-all ${
                  isStars
                    ? `h-9 w-9 text-2xl leading-none ${active ? 'text-copper' : 'text-ink-faint/35 hover:text-copper/50'}`
                    : `h-8 w-8 rounded-full border ${active ? 'border-copper bg-copper' : 'border-line bg-paper-raised hover:border-copper/50'}`
                }`}
              >
                {isStars ? (active ? '★' : '☆') : (
                  <span className={`font-mono text-xs ${active ? 'text-paper-raised' : 'text-ink-faint'}`}>{v}</span>
                )}
              </button>
            );
          })}
          {value !== undefined && (
            <span className="ml-2 font-mono text-sm text-ink-soft">
              {value}/{item.max}
              {item.labels?.[value - 1] ? ` · ${item.labels[value - 1]}` : ''}
            </span>
          )}
        </div>
      )}

      {(item.minLabel || item.maxLabel) && (
        <div className="mt-2 flex justify-between font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
          <span>{item.minLabel}</span>
          <span>{item.maxLabel}</span>
        </div>
      )}
    </ItemShell>
  );
}

